// 材質的顏色是用 sRGB 寫的，轉成線性空間才不會被洗白（同一個材質只轉一次）
function linMat(m){if(!m||m.userData.lin)return;m.userData.lin=true;if(m.color)m.color.convertSRGBToLinear();if(m.emissive)m.emissive.convertSRGBToLinear()}
function linColors(root){root.traverse(o=>{if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(linMat)})}
