camera.rotation.order='YXZ';scene.add(camera);
{
  const pm=new THREE.PMREMGenerator(renderer),es=new THREE.Scene();
  const g=new THREE.SphereGeometry(50,32,16),p=g.attributes.position,col=[];
  for(let i=0;i<p.count;i++){const t=(p.getY(i)/50+1)/2;col.push(.42+t*.55,.38+t*.6,.3+t*.72)}
  g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
  es.add(new THREE.Mesh(g,new THREE.MeshBasicMaterial({side:THREE.BackSide,vertexColors:true})));
  [[20,30,10],[-25,22,-10],[0,35,-25]].forEach(([x,y,z])=>{const b=new THREE.Mesh(new THREE.BoxGeometry(14,2,14),new THREE.MeshBasicMaterial({color:0xffffff}));b.position.set(x,y,z);b.lookAt(0,0,0);es.add(b)});
  scene.environment=pm.fromScene(es,.03).texture;
}
const hemi=new THREE.HemisphereLight(0xe8f2ff,0x8a6a40,.75);scene.add(hemi);
let skyGeo=null;const clouds=[];
const sun=new THREE.DirectionalLight(0xfff0d8,1.9);
sun.castShadow=true;sun.shadow.mapSize.set(4096,4096);sun.shadow.bias=-.0004;sun.shadow.normalBias=.02;sun.shadow.radius=3;
// 天空：漸層天頂＋幾朵雲
{
  const g=new THREE.SphereGeometry(320,32,16),p=g.attributes.position,col=[],top=new THREE.Color(0x3f86d6).convertSRGBToLinear(),hor=new THREE.Color(0xd8e8f2).convertSRGBToLinear(),c=new THREE.Color();
  for(let i=0;i<p.count;i++){const t=Math.max(0,p.getY(i)/320);c.copy(hor).lerp(top,Math.pow(t,.55));col.push(c.r,c.g,c.b)}
  g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
  skyGeo=g;const sky=new THREE.Mesh(g,new THREE.MeshBasicMaterial({side:THREE.BackSide,vertexColors:true,fog:false,depthWrite:false}));sky.userData.lin=true;sky.renderOrder=-1;scene.add(sky);
  const cloudTex=(()=>{const cc=document.createElement('canvas');cc.width=cc.height=256;const x=cc.getContext('2d');for(let k=0;k<26;k++){const r=30+Math.random()*50,gx=60+Math.random()*136,gy=90+Math.random()*60,gr=x.createRadialGradient(gx,gy,0,gx,gy,r);gr.addColorStop(0,'rgba(255,255,255,.9)');gr.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=gr;x.fillRect(0,0,256,256)}const t=new THREE.CanvasTexture(cc);t.encoding=THREE.sRGBEncoding;return t})();
  for(let k=0;k<9;k++){const a=k/9*6.283+Math.random(),r=120+Math.random()*80,cl=new THREE.Mesh(new THREE.PlaneGeometry(90,45),new THREE.MeshBasicMaterial({map:cloudTex,transparent:true,depthWrite:false,fog:false,opacity:.85}));cl.position.set(Math.cos(a)*r,55+Math.random()*30,Math.sin(a)*r);cl.lookAt(0,0,0);cl.userData.lin=true;scene.add(cl);clouds.push(cl)}
}
scene.add(sun,sun.target);

function canvasTex(w,h,draw,rep){const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);const t=new THREE.CanvasTexture(c);t.anisotropy=8;t.encoding=THREE.sRGBEncoding;if(rep){t.wrapS=t.wrapT=THREE.RepeatWrapping}return t}
const noise=(g,w,h,n,f)=>{for(let i=0;i<n;i++){g.fillStyle=f(Math.random());g.fillRect(Math.random()*w,Math.random()*h,2,2)}};
const sandTex=canvasTex(256,256,(g,w,h)=>{g.fillStyle='#a88a66';g.fillRect(0,0,w,h);noise(g,w,h,9000,v=>`rgb(${130+v*55|0},${104+v*45|0},${74+v*35|0})`)},true);
const plankTex=canvasTex(256,256,(g,w,h)=>{for(let x=0;x<w;x+=21){g.fillStyle=`hsl(${22+Math.random()*6},${30+Math.random()*12}%,${26+Math.random()*10}%)`;g.fillRect(x,0,20,h);g.fillStyle='#1d120a';g.fillRect(x+20,0,1,h)}noise(g,w,h,3000,v=>`rgba(20,10,0,${v*.3})`)},true);
const corrTex=canvasTex(256,256,(g,w,h)=>{g.fillStyle='#55524d';g.fillRect(0,0,w,h);for(let x=0;x<w;x+=16){g.fillStyle='#67625b';g.fillRect(x,0,7,h);g.fillStyle='#403d39';g.fillRect(x+12,0,3,h)}noise(g,w,h,1500,v=>`rgba(40,30,20,${v*.25})`)},true);
const concTex=canvasTex(256,128,(g,w,h)=>{g.fillStyle='#7d7a75';g.fillRect(0,0,w,h);noise(g,w,h,4000,v=>`rgba(${80+v*80|0},${80+v*75|0},${75+v*70|0},.6)`)},true);
const woodTex=canvasTex(256,256,(g,w,h)=>{for(let y=0;y<h;y+=32){g.fillStyle=`hsl(28,${35+Math.random()*10}%,${28+Math.random()*8}%)`;g.fillRect(0,y,w,31);g.fillStyle='#2a1b10';g.fillRect(0,y+31,w,1)}noise(g,w,h,2500,v=>`rgba(20,10,0,${v*.25})`)},true);
const shutterTex=canvasTex(128,256,(g,w,h)=>{g.fillStyle='#4c5a52';g.fillRect(0,0,w,h);for(let y=0;y<h;y+=16){g.fillStyle='#3a463f';g.fillRect(0,y,w,3);g.fillStyle='#5f6f66';g.fillRect(0,y+4,w,2)}});
const hazardTex=canvasTex(256,32,(g,w,h)=>{g.fillStyle='#222';g.fillRect(0,0,w,h);g.fillStyle='#e8a817';for(let x=-32;x<w;x+=32){g.beginPath();g.moveTo(x,h);g.lineTo(x+16,h);g.lineTo(x+32,0);g.lineTo(x+16,0);g.fill()}});
const beltTex=canvasTex(64,64,(g,w,h)=>{g.fillStyle='#2a2a2c';g.fillRect(0,0,w,h);g.strokeStyle='#e8e8e8';g.lineWidth=6;g.lineCap='square';g.beginPath();g.moveTo(16,40);g.lineTo(32,24);g.lineTo(48,40);g.stroke()},true);
// 共用的東西登記在 SHARED，拆機器時不會被釋放
const SHARED=new WeakSet(),share=o=>{SHARED.add(o);return o};
const _stc=new Map();
const signTex=(t,bg,fg,sub,w=512)=>{const k=[t,bg,fg,sub,w].join('|');let x=_stc.get(k);if(!x){x=share(signTexRaw(t,bg,fg,sub,w));_stc.set(k,x)}return x};
const signTexRaw=(t,bg,fg,sub,w=512)=>canvasTex(w,128,(g)=>{g.fillStyle=bg;g.fillRect(0,0,w,128);g.strokeStyle=fg;g.lineWidth=6;g.strokeRect(8,8,w-16,112);g.fillStyle=fg;g.textAlign='center';g.textBaseline='middle';g.font='900 '+(sub?54:64)+'px "Georgia","Microsoft JhengHei",serif';g.fillText(t,w/2,sub?50:66);if(sub){g.font='bold 26px "Microsoft JhengHei",sans-serif';g.fillText(sub,w/2,100)}});
const faceTex=num=>canvasTex(128,128,(g)=>{g.fillStyle='#fff';g.fillRect(0,0,128,128);g.strokeStyle='#8f8f8f';g.lineWidth=5;g.beginPath();g.arc(64,64,56,0,7);g.stroke();g.fillStyle='#707070';g.font='bold '+(num>=10?54:66)+'px sans-serif';g.textAlign='center';g.textBaseline='middle';g.fillText(num,64,68)});
const gaugeTex=canvasTex(256,256,(g)=>{g.fillStyle='#f3ead6';g.beginPath();g.arc(128,128,124,0,7);g.fill();g.strokeStyle='#3a2a1a';g.lineWidth=8;g.stroke();g.fillStyle='#222';g.font='bold 20px sans-serif';g.textAlign='center';g.textBaseline='middle';for(let k=0;k<=5;k++){const a=Math.PI*.75+k/5*Math.PI*1.5;g.fillText(k*10,128+Math.cos(a)*92,128+Math.sin(a)*92);g.save();g.translate(128+Math.cos(a)*112,128+Math.sin(a)*112);g.rotate(a);g.fillRect(-8,-2,16,4);g.restore()}g.font='bold 22px Georgia,serif';g.fillText('Coins',128,190)});
const padTex=canvasTex(256,256,(g,w,h)=>{g.fillStyle='#3a3d40';g.fillRect(0,0,w,h);g.strokeStyle='#e8c23a';g.lineWidth=14;g.beginPath();g.arc(128,128,100,0,7);g.stroke();g.fillStyle='#f2f2f2';g.font='900 130px "Arial Black",sans-serif';g.textAlign='center';g.textBaseline='middle';g.fillText('H',128,136)});
const drawerTex=canvasTex(256,256,(g,w,h)=>{g.fillStyle='#3a2414';g.fillRect(0,0,w,h);for(let y=0;y<6;y++)for(let x=0;x<4;x++){g.fillStyle='#5a3a20';g.fillRect(8+x*62,8+y*41,56,35);g.fillStyle='#efe8d6';g.fillRect(20+x*62,16+y*41,32,10);g.fillStyle='#c8a050';g.fillRect(32+x*62,32+y*41,8,4)}});

const M_={
  conc:new THREE.MeshStandardMaterial({map:concTex,roughness:.95,envMapIntensity:.4}),
  plank:new THREE.MeshStandardMaterial({map:plankTex,roughness:.9,envMapIntensity:.3}),
  corr:new THREE.MeshStandardMaterial({map:corrTex,roughness:.75,metalness:.35}),
  wood:new THREE.MeshStandardMaterial({map:woodTex,roughness:.85,envMapIntensity:.4}),
  dark:new THREE.MeshStandardMaterial({color:0x2c2c2e,roughness:.6,metalness:.5}),
  steel:new THREE.MeshStandardMaterial({color:0x8d949a,roughness:.35,metalness:.85}),
  green:new THREE.MeshStandardMaterial({color:0x44613a,roughness:.55,metalness:.35}),
  yellow:new THREE.MeshStandardMaterial({color:0xe2a51c,roughness:.5,metalness:.3}),
  rib:new THREE.MeshStandardMaterial({color:0x3a3d40,roughness:.5,metalness:.7}),
  glass:new THREE.MeshStandardMaterial({color:0xeaf4ff,transparent:true,opacity:.14,roughness:.1,side:THREE.DoubleSide,depthWrite:false}),
  belt:new THREE.MeshStandardMaterial({map:beltTex,roughness:.9}),
  skin:new THREE.MeshStandardMaterial({color:0xd9a882,roughness:.7}),
  gold:new THREE.MeshStandardMaterial({color:0xd6b45a,metalness:.85,roughness:.32}),
  heap:new THREE.MeshStandardMaterial({metalness:.75,roughness:.35,map:canvasTex(256,256,(g,w,h)=>{g.fillStyle='#8c8a80';g.fillRect(0,0,w,h);for(let k=0;k<260;k++){const x=Math.random()*w,y=Math.random()*h,r=9+Math.random()*7,c=Math.random()<.25?['#e6c36a','#9a7a2a']:['#e4e6e8','#8e9296'],gr=g.createRadialGradient(x-r*.3,y-r*.3,1,x,y,r);gr.addColorStop(0,c[0]);gr.addColorStop(1,c[1]);g.fillStyle=gr;g.beginPath();g.ellipse(x,y,r,r*(.5+Math.random()*.5),Math.random()*3,0,7);g.fill();g.strokeStyle='#0004';g.stroke()}},true)}),
  copper:new THREE.MeshStandardMaterial({color:0xcf9447,metalness:.9,roughness:.25,emissive:0x2a1400})
};
let coinGeo=share(new THREE.CylinderGeometry(1,1,1,20));
Object.values(M_).forEach(share);
// 硬幣側邊的齒紋
const reedTex=canvasTex(256,16,(g,w,h)=>{g.fillStyle='#fff';g.fillRect(0,0,w,h);for(let x=0;x<w;x+=4){g.fillStyle='#9a9a9a';g.fillRect(x,0,2,h)}},true);reedTex.repeat.set(4,1);
// 20 元是雙色硬幣：外圈銀色、中間金色
const bimetalTex=()=>canvasTex(256,256,g=>{g.fillStyle='#cfd3d6';g.beginPath();g.arc(128,128,126,0,7);g.fill();g.fillStyle='#d6b04e';g.beginPath();g.arc(128,128,82,0,7);g.fill();
  g.strokeStyle='#9aa0a4';g.lineWidth=3;g.beginPath();g.arc(128,128,82,0,7);g.stroke();g.fillStyle='#7a5a18';g.font='900 74px "Arial Black",sans-serif';g.textAlign='center';g.textBaseline='middle';g.fillText('20',128,134);
  g.fillStyle='#6d7276';g.font='bold 22px "Microsoft JhengHei",sans-serif';const tx='中華民國　貳拾圓';for(let k=0;k<tx.length;k++){const a=-Math.PI*.95+k*(Math.PI*1.9/tx.length);g.save();g.translate(128+Math.cos(a)*104,128+Math.sin(a)*104);g.rotate(a+Math.PI/2);g.fillText(tx[k],0,0);g.restore()}});
const COINMAT=CT.map(t=>{const o={color:t.color,metalness:.85,roughness:.32},s=new THREE.MeshStandardMaterial({...o,color:t.num===20?0xcfd3d6:t.color,map:t.num===10||t.num===5||t.num===20?reedTex:null}),f=new THREE.MeshStandardMaterial({...o,metalness:t.num===20?.6:.85,map:t.num===20?bimetalTex():faceTex(t.num)});return[s,f,f]});
// 使用者提供的硬幣照片（下載資料夾的 五十元.jpg、十元.jpg、五元.jpg、一元.jpg），嵌在檔案裡才不會被瀏覽器擋
const COIN_IMG={'50':'data:image/jpeg;base64,','10':'data:image/jpeg;base64,','5':'data:image/jpeg;base64,','1':'data:image/jpeg;base64,'};
const oneFace=new THREE.MeshStandardMaterial({color:0xcf9447,metalness:.6,roughness:.35});let oneImgURL='';
function coinCanvas(src,cb){
  const im=new Image();im.onload=()=>{
    const t=document.createElement('canvas');t.width=im.width;t.height=im.height;const tg=t.getContext('2d');tg.drawImage(im,0,0);
    const d=tg.getImageData(0,0,im.width,im.height).data;let x0=im.width,y0=im.height,x1=0,y1=0;
    for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++){const k=(y*im.width+x)*4;if(d[k]<225||d[k+1]<225||d[k+2]<225){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}}
    const s=Math.max(x1-x0,y1-y0)+1,cx=(x0+x1+1)/2,cy=(y0+y1+1)/2,W=512;
    const flat=document.createElement('canvas');flat.width=flat.height=W;flat.getContext('2d').drawImage(im,cx-s/2,cy-s/2,s,s,0,0,W,W);
    // 圓柱頂面的 UV 是轉過的，先把圖轉成對應方向，硬幣上的字才不會反過來
    const c=document.createElement('canvas');c.width=c.height=W;const g=c.getContext('2d');g.setTransform(0,-1,1,0,0,W);g.drawImage(flat,0,0);
    cb(c,flat)};
  im.src=src;
}
function loadCoinFaces(){
  [['50',0],['10',1],['5',2]].forEach(([key,k])=>{if(!COIN_IMG[key])return;coinCanvas(COIN_IMG[key],c=>{const tex=new THREE.CanvasTexture(c);tex.encoding=THREE.sRGBEncoding;tex.anisotropy=8;
    [COINMAT[k][1],COINMAT[k][2]].forEach(m=>{m.map=tex;m.color.setRGB(.82,.82,.82);m.metalness=.5;m.roughness=.42;m.envMapIntensity=.8;m.needsUpdate=true})})});
  if(COIN_IMG['1'])coinCanvas(COIN_IMG['1'],(c,flat)=>{const tex=new THREE.CanvasTexture(c);tex.encoding=THREE.sRGBEncoding;oneFace.map=tex;oneFace.color.setRGB(1,1,1);oneFace.needsUpdate=true;oneImgURL=flat.toDataURL()});
}
loadCoinFaces();

